from heapq import heappop, heappush

def cheapest(graph, start, goal):
    if start not in graph or goal not in graph:
        raise KeyError('start and goal must be nodes')
    for edges in graph.values():
        for neighbor, weight in edges:
            if neighbor not in graph or type(weight) is not int or weight < 0:
                raise ValueError('use known nodes and nonnegative integer weights')
    best, previous = {start: 0}, {}
    heap = [(0, start)]
    while heap:
        cost, node = heappop(heap)
        if cost != best[node]:
            continue  # An older, worse entry.
        if node == goal:
            break
        for neighbor, weight in graph[node]:
            candidate = cost + weight
            if candidate < best.get(neighbor, float('inf')):
                best[neighbor] = candidate
                previous[neighbor] = node
                heappush(heap, (candidate, neighbor))
    if goal not in best:
        return None
    path = [goal]
    while path[-1] != start:
        path.append(previous[path[-1]])
    path.reverse()
    return best[goal], path

