graph = {'A': [('B', 4), ('C', 1)], 'B': [('D', 1)], 'C': [('B', 2), ('D', 5)], 'D': []}
assert cheapest(graph, 'A', 'D') == (4, ['A', 'C', 'B', 'D'])
print('weighted route checked')

